import { useEffect, useRef, useState } from "react";
import {
  ArrowDown,
  ArrowUpRight,
  Camera,
  CheckCircle2,
  Clock3,
  Flame,
  MapPin,
  ShieldAlert,
  WifiOff,
} from "lucide-react";

const stats = [
  {
    label: "Detection",
    value: "Fire",
    icon: Flame,
  },
  {
    label: "Location",
    value: "Zone B · Floor 2",
    icon: MapPin,
  },
  {
    label: "Camera",
    value: "CAM-024",
    icon: Camera,
  },
  {
    label: "Status",
    value: "Active",
    icon: ShieldAlert,
  },
];

const edgeCases = [
  {
    title: "No active alert",
    description:
      "The dashboard clearly communicates that the facility is clear instead of leaving an ambiguous empty state.",
    icon: CheckCircle2,
  },
  {
    title: "Camera offline",
    description:
      "Disconnected cameras are surfaced as a system state so missing information is not mistaken for a clear environment.",
    icon: WifiOff,
  },
  {
    title: "Multiple alerts",
    description:
      "Different incidents remain distinguishable by location, type, severity and status.",
    icon: ShieldAlert,
  },
  {
    title: "Historical incidents",
    description:
      "Resolved events remain available through the detection history for investigation and review.",
    icon: Clock3,
  },
];

function Reveal({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const element = ref.current;

    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.12 }
    );

    observer.observe(element);

    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={`transition-all duration-700 ease-out ${
        visible
          ? "translate-y-0 opacity-100"
          : "translate-y-8 opacity-0"
      } ${className}`}
    >
      {children}
    </div>
  );
}

function FloorMap() {
  return (
    <div className="relative aspect-[16/9] overflow-hidden rounded-[2px] border border-black/[0.08] bg-[#eeeae4] dark:border-white/[0.08] dark:bg-[#181818]">
      {/* Grid */}
      <div
        className="absolute inset-0 opacity-50"
        style={{
          backgroundImage:
            "linear-gradient(rgba(0,0,0,.05) 1px, transparent 1px), linear-gradient(90deg, rgba(0,0,0,.05) 1px, transparent 1px)",
          backgroundSize: "36px 36px",
        }}
      />

      {/* Floor plan */}
      <div className="absolute left-[10%] top-[12%] h-[72%] w-[80%] border-2 border-black/20 dark:border-white/20">
        <div className="absolute left-0 top-1/2 h-px w-full bg-black/15 dark:bg-white/15" />

        <div className="absolute left-1/3 top-0 h-full w-px bg-black/15 dark:bg-white/15" />

        <div className="absolute left-2/3 top-0 h-full w-px bg-black/15 dark:bg-white/15" />

        <div className="absolute left-1/3 top-1/2 h-px w-1/3 bg-black/15 dark:bg-white/15" />
      </div>

      {/* Zone labels */}
      <span className="absolute left-[15%] top-[20%] text-[11px] font-medium uppercase tracking-[0.15em] text-neutral-400">
        Zone A
      </span>

      <span className="absolute left-[47%] top-[20%] text-[11px] font-medium uppercase tracking-[0.15em] text-neutral-400">
        Zone B
      </span>

      <span className="absolute left-[74%] top-[20%] text-[11px] font-medium uppercase tracking-[0.15em] text-neutral-400">
        Zone C
      </span>

      {/* Cameras */}
      {[
        { left: "23%", top: "36%" },
        { left: "47%", top: "36%" },
        { left: "69%", top: "36%" },
        { left: "31%", top: "65%" },
        { left: "56%", top: "65%" },
        { left: "76%", top: "65%" },
      ].map((camera, index) => (
        <div
        //   key={index}
          className={`absolute h-3 w-3 rounded-full border-2 border-white shadow-sm ${
            index === 1
              ? "animate-pulse bg-red-500"
              : "bg-neutral-500"
          }`}
          style={{
            left: camera.left,
            top: camera.top,
          }}
        />
      ))}

      {/* Active incident */}
      <div className="absolute left-[42%] top-[29%]">
        <div className="absolute -inset-5 animate-ping rounded-full bg-red-500/20" />

        <div className="relative flex h-10 w-10 items-center justify-center rounded-full bg-red-500 text-white shadow-lg">
          <Flame size={18} />
        </div>
      </div>

      {/* Incident popup */}
      <div className="absolute left-[50%] top-[24%] w-[220px] rounded-xl border border-black/[0.08] bg-white/95 p-4 shadow-xl backdrop-blur-sm dark:border-white/[0.08] dark:bg-[#202020]/95">
        <div className="flex items-start justify-between">
          <div>
            <p className="text-[11px] font-medium uppercase tracking-[0.12em] text-red-500">
              Active detection
            </p>

            <p className="mt-1 text-[15px] font-medium">
              Fire detected
            </p>
          </div>

          <Flame size={17} className="text-red-500" />
        </div>

        <div className="mt-3 space-y-1 text-[12px] text-neutral-500 dark:text-neutral-400">
          <p>CAM-024 · Zone B</p>
          <p>Confidence 96%</p>
          <p>Severity Critical</p>
        </div>
      </div>

      {/* Map label */}
      <div className="absolute bottom-5 left-5 rounded-full border border-black/[0.08] bg-white/80 px-4 py-2 text-[11px] font-medium uppercase tracking-[0.14em] text-neutral-500 backdrop-blur-sm dark:border-white/[0.08] dark:bg-black/30">
        Floor 02 · Live
      </div>
    </div>
  );
}

export default function Fire() {
  return (
    <div className="min-h-screen bg-[#3f3019] text-neutral-950 transition-colors duration-300 dark:bg-[#111111] dark:text-neutral-100">

      {/* Page rails */}
      <div className="mx-auto min-h-screen w-full max-w-[1180px] border-x border-black/[0.06] dark:border-white/[0.07]">

        {/* Hero */}
        <section className="px-6 pb-28 pt-20 sm:px-10 sm:pt-28 lg:px-14">
          <Reveal>
            <div className="flex items-center gap-3 text-[13px] font-medium uppercase tracking-[0.18em] text-neutral-400">
              <span className="h-2 w-2 rounded-full bg-red-500" />
              Fire & Smoke Detection
            </div>
          </Reveal>

          <Reveal className="mt-8 max-w-[900px]">
            <h1 className="font-serif text-[52px] leading-[0.98] tracking-[-0.045em] sm:text-[76px] lg:text-[92px]">
              Turning an alert into an actionable location.
            </h1>
          </Reveal>

          <Reveal className="mt-8 max-w-[650px]">
            <p className="text-[19px] leading-8 text-neutral-500 dark:text-neutral-400 sm:text-[21px]">
              A fire and smoke monitoring dashboard redesigned around
              the physical environment — helping employees understand
              where an incident is happening, what was detected and
              what needs attention.
            </p>
          </Reveal>

          {/* Meta */}
          <Reveal className="mt-12 grid grid-cols-2 gap-y-7 border-y border-black/[0.1] py-7 dark:border-white/[0.1] sm:grid-cols-4">
            <div>
              <p className="text-[12px] uppercase tracking-[0.15em] text-neutral-400">
                Role
              </p>
              <p className="mt-2 text-[15px]">
                UX/UI Product Designer
              </p>
            </div>

            <div>
              <p className="text-[12px] uppercase tracking-[0.15em] text-neutral-400">
                Product
              </p>
              <p className="mt-2 text-[15px]">
                Industrial Monitoring
              </p>
            </div>

            <div>
              <p className="text-[12px] uppercase tracking-[0.15em] text-neutral-400">
                Focus
              </p>
              <p className="mt-2 text-[15px]">
                UX · UI · Information Architecture
              </p>
            </div>

            <div>
              <p className="text-[12px] uppercase tracking-[0.15em] text-neutral-400">
                Platform
              </p>
              <p className="mt-2 text-[15px]">
                Desktop
              </p>
            </div>
          </Reveal>

          {/* Hero visual */}
          <Reveal className="mt-20">
            <div className="overflow-hidden bg-white p-2 shadow-[0_20px_80px_rgba(0,0,0,0.06)] dark:bg-[#191919]">
              <FloorMap />
            </div>
          </Reveal>
        </section>

        {/* Problem */}
        <section className="border-t border-black/[0.08] px-6 py-28 dark:border-white/[0.08] sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="01" label="The problem" />

            <div className="mt-12 grid gap-12 lg:grid-cols-[1fr_1.5fr]">
              <h2 className="font-serif text-[42px] leading-[1.05] tracking-[-0.035em] sm:text-[56px]">
                An alert existed. Context didn't.
              </h2>

              <div className="space-y-6 text-[18px] leading-8 text-neutral-500 dark:text-neutral-400">
                <p>
                  The initial dashboard could tell an employee that
                  an alert had been triggered, but it didn't help them
                  quickly understand where the incident was or how
                  serious it was.
                </p>

                <p>
                  The employee still had to connect the alert with a
                  camera and then determine where that camera was
                  physically located.
                </p>

                <p className="font-medium text-neutral-950 dark:text-neutral-100">
                  In an emergency, that extra mental step matters.
                </p>
              </div>
            </div>
          </Reveal>
        </section>

        {/* Insight */}
        <section className="px-6 py-28 sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="02" label="The insight" />

            <div className="mt-12 max-w-[900px]">
              <p className="font-serif text-[40px] leading-[1.12] tracking-[-0.035em] sm:text-[54px]">
                The problem wasn't detection.
                <br />
                It was understanding.
              </p>

              <p className="mt-8 max-w-[650px] text-[18px] leading-8 text-neutral-500 dark:text-neutral-400">
                Instead of making the alert more prominent, I changed
                the central concept of the dashboard. The interface
                needed to connect the detection directly to the
                physical environment.
              </p>
            </div>
          </Reveal>
        </section>

        {/* Solution */}
        <section className="border-y border-black/[0.08] py-28 dark:border-white/[0.08]">
          <div className="px-6 sm:px-10 lg:px-14">
            <Reveal>
              <SectionNumber number="03" label="The solution" />

              <div className="mt-12 grid gap-12 lg:grid-cols-[1fr_1.5fr]">
                <h2 className="font-serif text-[42px] leading-[1.05] tracking-[-0.035em] sm:text-[56px]">
                  From alert-centric to location-centric.
                </h2>

                <p className="text-[18px] leading-8 text-neutral-500 dark:text-neutral-400">
                  I introduced a floor-map experience with camera
                  locations, allowing an active detection to be
                  understood in its physical context. Supporting
                  information was structured around the questions an
                  employee needs to answer immediately.
                </p>
              </div>
            </Reveal>

            {/* Information cards */}
            <Reveal className="mt-16">
              <div className="grid grid-cols-2 border-l border-t border-black/[0.08] dark:border-white/[0.08] sm:grid-cols-4">
                {stats.map((stat) => {
                  const Icon = stat.icon;

                  return (
                    <div
                      key={stat.label}
                      className="group border-b border-r border-black/[0.08] p-5 transition-all duration-300 hover:-translate-y-1 hover:bg-white dark:border-white/[0.08] dark:hover:bg-[#191919] sm:p-7"
                    >
                      <Icon
                        size={19}
                        strokeWidth={1.5}
                        className="text-neutral-400 transition-transform duration-300 group-hover:scale-110"
                      />

                      <p className="mt-10 text-[12px] uppercase tracking-[0.14em] text-neutral-400">
                        {stat.label}
                      </p>

                      <p className="mt-2 text-[17px] font-medium">
                        {stat.value}
                      </p>
                    </div>
                  );
                })}
              </div>
            </Reveal>
          </div>
        </section>

        {/* UX Flow */}
        <section className="px-6 py-28 sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="04" label="The experience" />

            <h2 className="mt-12 max-w-[850px] font-serif text-[42px] leading-[1.05] tracking-[-0.035em] sm:text-[58px]">
              A clearer path from detection to investigation.
            </h2>

            <div className="mt-16 grid gap-0 border-l border-t border-black/[0.08] dark:border-white/[0.08] md:grid-cols-4">
              {[
                ["01", "Live dashboard", "See the facility state and active incidents."],
                ["02", "Location", "Identify the affected floor, zone and camera."],
                ["03", "Incident", "Understand type, severity, confidence and status."],
                ["04", "History", "Investigate previous detections and camera activity."],
              ].map(([number, title, description]) => (
                <div
                  key={number}
                  className="border-b border-r border-black/[0.08] p-7 dark:border-white/[0.08]"
                >
                  <span className="font-mono text-[12px] text-neutral-400">
                    {number}
                  </span>

                  <h3 className="mt-12 text-[19px] font-medium">
                    {title}
                  </h3>

                  <p className="mt-3 text-[15px] leading-6 text-neutral-500 dark:text-neutral-400">
                    {description}
                  </p>
                </div>
              ))}
            </div>
          </Reveal>
        </section>

        {/* Edge cases */}
        <section className="border-t border-black/[0.08] px-6 py-28 dark:border-white/[0.08] sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="05" label="Edge cases" />

            <div className="mt-12 grid gap-10 lg:grid-cols-[0.8fr_2fr]">
              <h2 className="font-serif text-[42px] leading-[1.05] tracking-[-0.035em] sm:text-[54px]">
                Monitoring can't assume everything is normal.
              </h2>

              <div className="grid gap-px bg-black/[0.08] dark:bg-white/[0.08] sm:grid-cols-2">
                {edgeCases.map((item) => {
                  const Icon = item.icon;

                  return (
                    <div
                      key={item.title}
                      className="group bg-[#f7f5f2] p-7 transition-all duration-300 hover:-translate-y-1 hover:bg-white dark:bg-[#111111] dark:hover:bg-[#191919]"
                    >
                      <Icon
                        size={20}
                        strokeWidth={1.5}
                        className="text-neutral-400 transition-transform duration-300 group-hover:scale-110"
                      />

                      <h3 className="mt-10 text-[18px] font-medium">
                        {item.title}
                      </h3>

                      <p className="mt-3 text-[15px] leading-6 text-neutral-500 dark:text-neutral-400">
                        {item.description}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          </Reveal>
        </section>

        {/* Tradeoffs */}
        <section className="border-t border-black/[0.08] px-6 py-28 dark:border-white/[0.08] sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="06" label="Trade-offs" />

            <div className="mt-12 grid gap-12 lg:grid-cols-[1fr_1.5fr]">
              <h2 className="font-serif text-[42px] leading-[1.05] tracking-[-0.035em] sm:text-[54px]">
                Show what matters.
                <br />
                Hide what doesn't.
              </h2>

              <div className="space-y-6 text-[18px] leading-8 text-neutral-500 dark:text-neutral-400">
                <p>
                  Monitoring products can easily become overloaded
                  with metrics, statuses and camera information.
                </p>

                <p>
                  I prioritized the information needed for immediate
                  response: <strong className="text-neutral-950 dark:text-white">location, incident type, severity, camera, time and status.</strong>
                </p>

                <p>
                  Deeper information moved into supporting views such
                  as camera status and detection history.
                </p>
              </div>
            </div>
          </Reveal>
        </section>

        {/* Learning */}
        <section className="border-t border-black/[0.08] px-6 py-32 dark:border-white/[0.08] sm:px-10 lg:px-14">
          <Reveal>
            <SectionNumber number="07" label="What I learned" />

            <div className="mt-12 max-w-[1000px]">
              <blockquote className="font-serif text-[38px] leading-[1.15] tracking-[-0.035em] sm:text-[56px]">
                “The most important information isn't always the
                information that's easiest to display.”
              </blockquote>

              <p className="mt-10 max-w-[700px] text-[18px] leading-8 text-neutral-500 dark:text-neutral-400">
                For operational products, I learned to start with the
                decision the user needs to make immediately after
                seeing the information. That shift helped me design
                the interface around action rather than simply
                displaying system output.
              </p>
            </div>
          </Reveal>
        </section>

        {/* Footer CTA */}
        <section className="border-t border-black/[0.08] px-6 py-20 dark:border-white/[0.08] sm:px-10 lg:px-14">
          <a
            href="/work"
            className="group flex items-center justify-between"
          >
            <div>
              <p className="text-[13px] uppercase tracking-[0.16em] text-neutral-400">
                Back to
              </p>

              <p className="mt-2 font-serif text-[36px] tracking-[-0.03em]">
                Selected Work
              </p>
            </div>

            <ArrowUpRight
              size={32}
              strokeWidth={1.3}
              className="transition-transform duration-300 group-hover:-translate-y-1 group-hover:translate-x-1"
            />
          </a>
        </section>
      </div>
    </div>
  );
}

function SectionNumber({
  number,
  label,
}: {
  number: string;
  label: string;
}) {
  return (
    <div className="flex items-center gap-4">
      <span className="font-mono text-[12px] text-neutral-400">
        {number}
      </span>

      <span className="text-[13px] font-medium uppercase tracking-[0.16em] text-neutral-400">
        {label}
      </span>
    </div>
  );
}
